export interface Diagnostic {
  /**
   * Closed, stable diagnostic identifier.
   */
  code: DiagnosticCode;
  /**
   * Severity of the finding.
   */
  severity: Severity;
  /**
   * Primary source range.
   */
  span: Span;
  /**
   * Concise explanation.
   */
  message: string;
  /**
   * Supporting notes.
   */
  notes?: Note[];
  /**
   * Suggested edits.
   */
  fixes?: Fix[];
}
/**
 * A half-open source range with one-based line and column coordinates.
 */
export interface Span {
  /**
   * Repository-relative source file identifier.
   */
  file: FileId;
  /**
   * Start line (one-based).
   */
  line: number;
  /**
   * Start column (one-based, Unicode scalar count).
   */
  col: number;
  /**
   * End line (one-based).
   */
  end_line: number;
  /**
   * End column (one-based, exclusive).
   */
  end_col: number;
}
/**
 * Additional explanation attached to a diagnostic.
 */
export interface Note {
  /**
   * Optional source location for the note.
   */
  span?: Span | null;
  /**
   * Human-readable explanation.
   */
  message: string;
}
/**
 * A source edit suggested by a diagnostic.
 */
export interface Fix {
  /**
   * Range replaced by this edit.
   */
  span: Span;
  /**
   * Replacement source text.
   */
  replacement: string;
  /**
   * Whether the edit can be applied without review.
   */
  applicability: Applicability;
}
/**
 * One `litigate` invocation over an in-memory file tree (litgraph-wasm's
 * `litigate`): what the CLI prints and exits with, and the files it wrote.
 */
export interface LitigateRun {
  /**
   * Exit code: 0 ok, 2 an error diagnostic, 1 usage or I/O.
   */
  code: number;
  /**
   * Standard output: the envelope (JSON, one line) or its human rendering.
   */
  stdout: string;
  /**
   * Standard error: a usage or I/O failure.
   */
  stderr: string;
  /**
   * Files written (`build`'s outputs), by normalized path.
   */
  files: {
    [k: string]: string | undefined;
  };
}
/**
 * A generated document's sidecar.
 */
export interface SourceMap {
  /**
   * The generated-file marker.
   */
  generated: Generated;
  /**
   * Document kind: `pack`, `links`, `clock`, or `scenario`.
   */
  kind: string;
  /**
   * Pack or scenario id (empty for links).
   */
  id: string;
  /**
   * Source package (absent for a case).
   */
  package?: PackageRef | null;
  /**
   * Law-in-force date the build selected versions at.
   */
  as_of: string;
  /**
   * Corpus date the build selected versions at.
   */
  known_at?: string | null;
  /**
   * Entries in document order.
   */
  entries: Entry[];
}
/**
 * Marks a file as compiler output: who generated it, from which language
 * version. Deterministic (no timestamps, no absolute paths).
 */
export interface Generated {
  /**
   * Always `litigate-lower`.
   */
  by: string;
  /**
   * Compiler version.
   */
  version: string;
  /**
   * Language version (SPEC §4.1 `language`).
   */
  language: number;
}
/**
 * The package a document was lowered from.
 */
export interface PackageRef {
  /**
   * Package name.
   */
  name: string;
  /**
   * Exact version.
   */
  version: string;
  /**
   * `sha256:<hex>` source digest (SPEC §4.2).
   */
  digest: string;
}
/**
 * One generated value and its origin.
 */
export interface Entry {
  /**
   * JSON pointer into the generated document (`/nodes/3`).
   */
  pointer: string;
  /**
   * The litgraph id there (`answer-due`, `respond->answered#0`).
   */
  id: string;
  /**
   * Declaring source span.
   */
  span?: Span | null;
  /**
   * The emitted version, `id@in-force-from`.
   */
  decl?: string | null;
  /**
   * The `cite` (nodes) or `authority` (edges), located in L0.
   */
  cite?: CiteMap | null;
}
/**
 * A cite string and where each of its citations is in L0.
 */
export interface CiteMap {
  /**
   * The emitted text.
   */
  text: string;
  /**
   * Each recognized rule/statute citation, in order.
   */
  sections?: L0Section[];
}
/**
 * One citation of a `cite`/`authority` string, located in the L0 corpus.
 */
export interface L0Section {
  /**
   * Canonical corpus heading (`Rule 12`, `28 U.S.C. § 1291`).
   */
  heading: string;
  /**
   * The `[sources.*]` binding it resolves through, when bound.
   */
  source?: string | null;
  /**
   * Repository-relative corpus file holding it, when vendored.
   */
  path?: string | null;
  /**
   * One-based line of its `## <heading>` line in `path`.
   */
  line?: number | null;
}
